INSERT INTO m5_question.questions (id, school_id, category_id, stem, answer_points) VALUES
  ('50000000-0000-0000-0000-000000000021', '10000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000011',
   '请结合新课标，谈谈你对“以学生为中心”的理解。',
   '以学生发展为本，尊重个体差异；关注学习过程与真实情境；教师从知识传授者转为学习设计者与引导者；评价关注增值与素养表现。'),
  ('50000000-0000-0000-0000-000000000022', '10000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000011',
   '请结合日常教学实例，谈谈如何在课堂教学中落实核心素养？',
   '围绕真实问题设计任务；创设情境促进迁移；采用合作探究与表现性评价；把知识学习与价值体认、实践创新结合起来。'),
  ('50000000-0000-0000-0000-000000000023', '10000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000012',
   '上课时发现学生偷偷玩手机，你会如何处理？',
   '先不打断课堂，用眼神或走近提醒；课后单独沟通，了解原因；按班规处理并保护学生自尊；与家长沟通，形成一致的手机管理约定。'),
  ('50000000-0000-0000-0000-000000000024', '10000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000012',
   '作为班主任，你如何营造积极向上、互助友爱的班级氛围？',
   '建立清晰且共同约定的班规；设置多元岗位与正向激励机制；开展合作性班级活动；关注边缘学生，及时化解矛盾；教师以身作则。'),
  ('50000000-0000-0000-0000-000000000025', '10000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000013',
   '正在上课时，一名学生突然晕倒在座位上，你该怎么办？',
   '立即停止授课并查看学生意识与呼吸；安排学生呼叫校医和拨打急救电话；保持现场通风，不随意搬动；通知家长和学校负责人并记录过程。'),
  ('50000000-0000-0000-0000-000000000026', '10000000-0000-0000-0000-000000000001', '50000000-0000-0000-0000-000000000013',
   '公开课上多媒体设备突然故障，你如何应对？',
   '保持镇定，先用板书或口头讲述继续教学；快速尝试切换备用设备；调整活动顺序，保证教学目标不中断；课后检查原因并做好预案。');

