INSERT INTO m3_classroom.session_texts
  (id, session_id, speaker_type, speaker_ref, source, kind, text, start_ms, end_ms, at_ms, confidence, status)
VALUES
  ('74000000-0000-0000-0000-000000000001', '70000000-0000-0000-0000-000000000001', 'teacher', NULL, 'asr', 'utterance', '同学们，今天我们学习《荷塘月色》。', 0, 3000, 1000, 0.95, 'final'),
  ('74000000-0000-0000-0000-000000000002', '70000000-0000-0000-0000-000000000001', 'student', '61000000-0000-0000-0000-000000000001', 'llm', 'answer', '老师，作者为什么反复写荷塘的月色？', 3000, 6000, 5000, 0.90, 'final'),
  ('74000000-0000-0000-0000-000000000003', '70000000-0000-0000-0000-000000000002', 'teacher', NULL, 'asr', 'utterance', '请大家默读课文，找出描写荷塘的句子。', 0, 3000, 1000, 0.94, 'final'),
  ('74000000-0000-0000-0000-000000000004', '70000000-0000-0000-0000-000000000002', 'student', '61000000-0000-0000-0000-000000000002', 'llm', 'answer', '老师，我觉得月色和荷塘是相互映衬的。', 3000, 6000, 5000, 0.91, 'final'),
  ('74000000-0000-0000-0000-000000000005', '70000000-0000-0000-0000-000000000003', 'teacher', NULL, 'asr', 'utterance', '我们来看这一段比喻句的表达效果。', 0, 3000, 1000, 0.93, 'final'),
  ('74000000-0000-0000-0000-000000000006', '70000000-0000-0000-0000-000000000003', 'student', '61000000-0000-0000-0000-000000000003', 'llm', 'answer', '把荷叶比作舞女的裙，写出了荷叶的轻盈。', 3000, 6000, 5000, 0.92, 'final'),
  ('74000000-0000-0000-0000-000000000007', '70000000-0000-0000-0000-000000000004', 'teacher', NULL, 'asr', 'utterance', '请同学们体会作者的情感变化。', 0, 3000, 1000, 0.95, 'final'),
  ('74000000-0000-0000-0000-000000000008', '70000000-0000-0000-0000-000000000004', 'student', '61000000-0000-0000-0000-000000000001', 'llm', 'answer', '作者从烦闷逐渐变得宁静。', 3000, 6000, 5000, 0.89, 'final'),
  ('74000000-0000-0000-0000-000000000009', '70000000-0000-0000-0000-000000000005', 'teacher', NULL, 'asr', 'utterance', '最后我们齐读课文最后三段。', 0, 3000, 1000, 0.96, 'final'),
  ('74000000-0000-0000-0000-000000000010', '70000000-0000-0000-0000-000000000005', 'student', '61000000-0000-0000-0000-000000000002', 'llm', 'answer', '老师，结尾的“猛一抬头”有什么作用？', 3000, 6000, 5000, 0.90, 'final');

